<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Bodega | CampoSur</title><link rel="stylesheet" href="/assets/css/app.css"></head><body class="admin-page"><main class="admin-shell"><?php require dirname(__DIR__) . '/Views/partials/module-navigation.php'; ?><section class="module-content"><header class="admin-header"><div><p class="eyebrow">Bodega</p><h1>Inventario</h1><p class="setup-copy">Registra tus insumos y revisa las entradas y salidas de la bodega.</p></div><a class="secondary-link" href="/">Volver al dashboard</a></header><?php if ($error): ?><div class="setup-error"><?= htmlspecialchars($error) ?></div><?php endif; ?><?php if ($success): ?><div class="setup-success"><?= htmlspecialchars($success) ?></div><?php endif; ?><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Nuevo artículo</h2><p>Catálogo de inventario</p></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="create_item"><label>SKU<input name="sku" required placeholder="INS-0001"></label><label>Nombre<input name="name" required placeholder="Fertilizante granulado"></label><label>Categoría<select name="category"><option value="INSUMO">Insumo</option><option value="FERRETERIA">Ferretería</option><option value="MAQUINARIA">Maquinaria</option><option value="HERRAMIENTA">Herramienta</option><option value="OTRO">Otro</option></select></label><label>Unidad<input name="unit" required placeholder="kg, lt, un"></label><label>Stock mínimo<input type="number" name="minimum_stock" min="0" step="0.001"></label><button class="primary-button" type="submit">Crear artículo</button></form></article><article class="admin-panel"><header class="panel-header"><h2>Registrar movimiento</h2><p>Entrada, salida o ajuste</p></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="create_movement"><label>Artículo<select name="item_id" required><?php foreach ($item_options as $item): ?><option value="<?= (int) $item['id'] ?>"><?= htmlspecialchars($item['sku'] . ' · ' . $item['name']) ?></option><?php endforeach; ?></select></label><label>Tipo<select name="movement_type"><option value="IN">Entrada</option><option value="OUT">Salida</option><option value="ADJUSTMENT">Ajuste</option></select></label><label>Cantidad<input type="number" name="quantity" min="0.001" step="0.001" required></label><label>Costo unitario<input type="number" name="unit_cost" min="0" step="0.01"></label><label>Fecha<input type="date" name="movement_date" required value="<?= date('Y-m-d') ?>"></label><label>Referencia<input name="reference" placeholder="Factura, vale o guía"></label><button class="primary-button" type="submit">Registrar movimiento</button></form></article></section><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Stock actual</h2><p>Existencia calculada por movimientos</p></header><div class="table-scroll"><table class="admin-table"><thead><tr><th>Artículo</th><th>Categoría</th><th>Unidad</th><th>Stock</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><b><?= htmlspecialchars($item['name']) ?></b><small><?= htmlspecialchars($item['sku']) ?></small></td><td><?= htmlspecialchars($item['category']) ?></td><td><?= htmlspecialchars($item['unit']) ?></td><td><b><?= number_format((float) $item['stock'], 3, ',', '.') ?></b></td></tr><?php endforeach; ?></tbody></table></div></article><article class="admin-panel"><header class="panel-header"><h2>Movimientos recientes</h2><p>Últimos 40 registros</p></header><div class="role-list"><?php foreach ($movements as $movement): ?><div class="role-row"><div><b><?= htmlspecialchars($movement['item_name']) ?></b><small><?= htmlspecialchars($movement['movement_date']) ?> · <?= htmlspecialchars($movement['reference'] ?? '') ?></small></div><span><?= htmlspecialchars($movement['movement_type']) ?> · <?= number_format((float) $movement['quantity'], 3, ',', '.') ?> <?= htmlspecialchars($movement['unit']) ?></span></div><?php endforeach; ?></div></article></section></section></main></body></html>
